import itertools, json

movies = ["H", "M", "R", "S", "W"]
# slots: (screen, time)
slots = [(1, 7), (1, 9), (2, 7), (2, 9), (3, 8)]

def valid(a):
    # a: movie -> slot
    if not a["W"][1] < a["H"][1]:
        return False
    if a["S"][0] == 3:
        return False
    if a["R"][0] == 2:
        return False
    if a["H"][0] == a["M"][0]:
        return False
    return True

sols = []
for perm in itertools.permutations(slots):
    a = dict(zip(movies, perm))
    if valid(a) and a["R"][1] < a["W"][1]:
        sols.append(a)

options = {
    "A": lambda a: a["H"][0] == 1,
    "B": lambda a: a["M"][1] == 7,
    "C": lambda a: a["M"][0] == 2,
    "D": lambda a: a["S"][1] == 9,
    "E": lambda a: a["S"][0] == 2,
}

must = [k for k, f in options.items() if sols and all(f(a) for a in sols)]

if len(must) == 1:
    print(json.dumps({
        "final_answer": must[0],
        "evidence": {"num_solutions": len(sols), "must_be_true": must}
    }))
else:
    print("UNSUPPORTED")
